contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount <= address(this).balance);
        require(depositAmount > 0);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Collect(collectAmount); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        assert(
            (balBefore < minSum || balBefore < collectAmount)
                ? (balAfter == balBefore && ethAfter == ethBefore)
                : (balAfter == balBefore - collectAmount && ethBefore - ethAfter == collectAmount)
        );
    }
    receive() external payable {}
}

